"""TK-010 chain (background): assign done -> apply to Mongo; sample60b Nominatim done -> gate on sample60b; then CHAIN_DONE."""
import os, subprocess, sys, time
T = 'C:/verger-data/pilot/tk010/'
R = 'C:/vdev/verger'
def wait(f, limit=3 * 3600):
    t = time.time()
    while not os.path.exists(f) and time.time() - t < limit: time.sleep(5)
    return os.path.exists(f)
def run(cmd, out):
    with open(T + out, 'w', encoding='utf8') as o:
        return subprocess.run(cmd, cwd=R, stdout=o, stderr=subprocess.STDOUT).returncode
if wait(T + 'ASSIGN_DONE'):
    run(['node', 'tools/tk010_apply.mjs'], 'apply.out')
    open(T + 'APPLY_DONE', 'w').write(time.strftime('%H:%M:%S'))
if wait(T + 'area60b.json'):
    run([sys.executable, '-I', 'tools/tk010_gate60.py', T + 'area60b.json', T + 'gate_labels60b.json'], 'gate60b_labels.out')
    run(['node', 'tools/tk010_gate60.mjs', T + 'area60b.json', T + 'raw60b.json', T + 'gate_labels60b.json', T + 'gate_tk010_60b.json'], 'gate60b.out')
    open(T + 'GATE60B_DONE', 'w').write(time.strftime('%H:%M:%S'))
open(T + 'CHAIN_DONE', 'w').write(time.strftime('%H:%M:%S'))

